CREATE OR REPLACE FUNCTION public.icash_claim_discovery_estimate(p_account uuid, p_scope jsonb, p_plan jsonb, p_policy jsonb, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e icash_research_private.estimates;peer icash_research_private.estimates;op text;generation timestamptz;t uuid:=gen_random_uuid();
begin
 if jsonb_typeof(p_query) is distinct from 'object' or octet_length(p_query::text)>16384
  or p_query->'estimate_cost' is distinct from 'true'::jsonb or p_query->>'contact_audience' is distinct from 'none'
  or p_query->>'anchor' is distinct from 'properties' then return jsonb_build_object('status','held');end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 perform 1 from public.icash_discovery_configs where account_id=p_account for update;
 if not public.icash_research_query_ready(p_account,p_scope,p_plan,p_policy) then return jsonb_build_object('status','held');end if;
 op:='discovery:'||p_account||':'||(p_scope->>'p_revision')||':'||(p_scope->>'p_page');
 if p_policy->>'exclusionListId' is not null then
  select last_synced_at into generation from icash_research_private.exclusions where id=1 and list_id=p_policy->>'exclusionListId';
  if generation is null then return jsonb_build_object('status','held');end if;
 end if;
 insert into icash_research_private.estimates(operation_key,account_id,query,exclusion_synced_at)
 values(op,p_account,p_query,generation) on conflict do nothing;
 select * into e from icash_research_private.estimates where operation_key=op and account_id=p_account for update;
 if not found or e.lease_until>now() then return jsonb_build_object('status','held');end if;
 if e.query=p_query and e.exclusion_synced_at is not distinct from generation then
  if e.response is not null and e.saved_at>now()-interval '5 minutes' then return jsonb_build_object('status','cached','response',e.response);end if;
  if e.retry_at>now() then return jsonb_build_object('status','held');end if;
 end if;

 -- The existing operating-budget lock serializes these claims across accounts.
 -- A lease survives the transaction and coalesces the actual free network call.
 -- Hash is an index aid only: exact JSON and exclusion generation must match.
 select * into peer from icash_research_private.estimates other
 where other.operation_key<>op and md5(other.query::text)=md5(p_query::text)
  and other.query=p_query and other.exclusion_synced_at is not distinct from generation
  and (other.lease_until>now() or other.retry_at>now()
   or (other.response is not null and other.saved_at between now()-interval '5 minutes' and now()))
 order by (other.response is not null and other.saved_at between now()-interval '5 minutes' and now()) desc nulls last,
  other.saved_at desc nulls last,other.operation_key limit 1;
 if found then
  if peer.response is not null and peer.saved_at between now()-interval '5 minutes' and now() then
   -- Share only the validated non-contact estimate fields. Keep its original age.
   update icash_research_private.estimates set shared_hits=shared_hits+1 where operation_key=peer.operation_key;
   return jsonb_build_object('status','cached','response',jsonb_build_object('estimated_credits',
    jsonb_build_object('this_page',peer.response#>'{estimated_credits,this_page}',
     'breakdown',jsonb_build_object('people',peer.response#>'{estimated_credits,breakdown,people}'))));
  end if;
  return jsonb_build_object('status','held');
 end if;
 update icash_research_private.estimates set query=p_query,exclusion_synced_at=generation,token=t,
  lease_until=now()+interval '1 minute',retry_at=null,response=null,saved_at=null,updated_at=now() where operation_key=op;
 return jsonb_build_object('status','request','token',t);
end $function$

CREATE OR REPLACE FUNCTION public.icash_finish_screening(p_id uuid, p_token uuid, p_result jsonb, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if p_error is not null and p_error not in ('INVALID_SNAPSHOT','SCREENING_FAILED') then raise exception 'Invalid error code'; end if;
 if p_error is null and (p_result is null or jsonb_typeof(p_result)<>'object' or octet_length(p_result::text)>65536) then raise exception 'Result required'; end if;
 update public.icash_screening_jobs set state=case when p_error is null then 'complete' else 'failed' end,
 result=p_result,error_code=p_error,completed_at=now(),lease_token=null,lease_until=null
 where id=p_id and state='running' and lease_token=p_token and lease_until>now();
 return found;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_research_discovery(p_account uuid, p_scope jsonb, p_plan jsonb, p_policy jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;ok boolean;op text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 -- Stabilize activation/list generation under the original budget/account/config locks.
 perform 1 from icash_research_private.targeting_query_settings where id=1 for share;
 perform 1 from icash_research_private.targeting_settings where id=1 for share;
 perform 1 from icash_research_private.targeting_experiments where id=(p_plan->'targeting'->>'id')::uuid for share;
 perform 1 from icash_research_private.exclusions where id=1 for share;
 if not icash_research_private.targeting_policy_allowed(p_account,p_scope,p_plan,p_policy) then return false;end if;
 if not public.icash_research_query_ready(p_account,p_scope,p_plan,p_policy) then return false;end if;
 op:='discovery:'||p_account||':'||(p_scope->>'p_revision')||':'||(p_scope->>'p_page');
 if p_plan->>'version'='seller-targeting-v1' or public.icash_targeting_query_context(p_account,(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer)->'required'='true'::jsonb then
  insert into icash_research_private.targeting_query_admissions(operation_key,account_id,transaction_id,scope,policy,exclusion_synced_at)
  select op,p_account,txid_current(),jsonb_build_object(
   'p_zip',p_scope->>'p_zip','p_revision',(p_scope->>'p_revision')::uuid,'p_page',(p_scope->>'p_page')::integer,
   'p_per_page',(p_scope->>'p_per_page')::integer,'p_rate',(p_scope->>'p_rate')::uuid,'p_unit',(p_scope->>'p_unit')::bigint,
   'p_permission_until',(p_scope->>'p_permission_until')::timestamptz,'p_setup_revision',(p_scope->>'p_setup_revision')::integer,
   'p_market_mode',p_scope->>'p_market_mode','p_market',p_scope->>'p_market'),p_policy,e.last_synced_at from icash_research_private.exclusions e where e.id=1;
 end if;
 if p_plan is not null then
  ok:=public.icash_reserve_and_claim_filtered_discovery(p_account,p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,(p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz,(p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market',p_plan);
 else
  ok:=public.icash_reserve_and_claim_property_discovery(p_account,p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,(p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz,(p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market');
 end if;
 delete from icash_research_private.targeting_query_admissions where operation_key=op and transaction_id=txid_current();
 if not ok then return false;end if;
 op:='discovery:'||p_account||':'||(p_scope->>'p_revision')||':'||(p_scope->>'p_page');
 insert into icash_research_private.query_claims values(op,p_account,p_policy);return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_targeting_query_context(p_account uuid, p_revision uuid, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;q icash_research_private.targeting_query_settings;e icash_research_private.exclusions;
 history boolean;active boolean;ready boolean;required boolean;policy jsonb;
begin
 select * into c from public.icash_discovery_configs where account_id=p_account and revision=p_revision and next_page=p_page;
 if not found then return jsonb_build_object('required',true,'ready',false,'policy',null);end if;
 select * into q from icash_research_private.targeting_query_settings where id=1;
 select * into e from icash_research_private.exclusions where id=1;
 history:=exists(select 1 from public.icash_discovery_filter_pages p where p.zip=c.zip
  and p.plan->>'version'='seller-targeting-v1' and p.state not in ('empty','unavailable'));
 active:=exists(select 1 from icash_research_private.targeting_experiments x where public.icash_targeting_available(p_account,c.zip,x.definition));
 ready:=coalesce(q.enabled and e.state='ready' and e.list_id=q.list_id and e.last_synced_at<=now()
  and e.last_synced_at is not null
  and not exists(select 1 from icash_research_private.exclusion_items where synced_at is null)
  and not exists(select 1 from icash_research_private.targeting_acquired_properties where synced_at is null)
  and not exists(select 1 from public.icash_operation_spend o
   cross join lateral (select array(select known.zip from (
    select fp.zip from public.icash_discovery_filter_pages fp where fp.operation_key=o.operation_key and fp.account_id=o.account_id
    union select public.icash_stalled_search_configuration(o.account_id,o.operation_key)->>'zip'
    union select estimate.query#>>'{locations,0,code}' from icash_research_private.estimates estimate
     where estimate.operation_key=o.operation_key and estimate.account_id=o.account_id
      and jsonb_array_length(case when jsonb_typeof(estimate.query->'locations')='array' then estimate.query->'locations' else '[]'::jsonb end)=1
      and estimate.query->'locations'=jsonb_build_array(jsonb_build_object('type','zip_code','code',estimate.query#>>'{locations,0,code}'))
    union select prior.zip from public.icash_discovery_configs prior where prior.account_id=o.account_id
     and o.operation_key='discovery:'||prior.account_id||':'||prior.revision||':'||prior.next_page
   ) known where known.zip ~ '^[0-9]{5}$') zips) scopes
   where o.operation_key like 'discovery:%' and o.state not in ('settled','cancelled')
    and not (o.operation_key='discovery:'||p_account||':'||p_revision||':'||p_page and o.state='reserved')
    and (cardinality(scopes.zips)=0 or c.zip=any(scopes.zips))),false);
 required:=history;
 if ready and (history or active) then policy:=jsonb_build_object('version',case when c.research_version=1 then 'research-efficiency-v1' else 'research-efficiency-v2' end,'exclusionListId',q.list_id);end if;
 return jsonb_build_object('required',required,'ready',ready and (history or active),'policy',policy);
end $function$
